    expect(JSON.stringify(status)).not.toContain('made-up');
    const accessed = [...read.mock.calls, ...open.mock.calls].map(([file]) => String(file));
    expect(accessed).not.toContain(overlay);
    expect(await snapshot(root)).toEqual(before);
  });

